import json
from ghidra.program.model.symbol import SymbolType
results = {}
sym = currentProgram.getSymbolTable()
# find anon labels used in upload_rt_world / find_mesh_mesh_intersections FrozenMap::get name compares
for prefix in ["107183261458dea85466985370debbb6_52", "107183261458dea85466985370debbb6_2_", "107183261458dea85466985370debbb6_93", "107183261458dea85466985370debbb6_35"]:
    it = sym.getSymbols(prefix)
    found = []
    for s in it:
        addr = s.getAddress()
        data = currentProgram.getMemory()
        b = []
        try:
            for i in range(0, 80):
                byte = data.getByte(addr.add(i))
                if byte == 0:
                    break
                b.append(byte)
        except Exception as e:
            pass
        found.append({"label": s.getName(), "address": str(addr), "bytes": b, "str": bytes(b).decode("utf-8", errors="replace")})
    results[prefix] = found
print(json.dumps(results))
